NQC_MINER_COLLECTION_INPUT_5
base64 -d <<'NQC_MINER_COLLECTION_INPUT_6' | gzip -d > "$MINER_TEST_EVIDENCE/holder.sql"
H4sIAAAAAAACA31TwY7aMBC98xVzQHJSLRGs2hPiAMGUqNkEhVTbm2USL7Ea7NSepcvf1w7N0t2V
mpPtmXnvzZvJZAJlI6DjRiiE31yihSdtABtpAQ1XllcotSIWju6GooZWVz/hIFyWAIvcoFRHqFrp
AGw0mkygEK3gVoBW7QX4EwoDB40NGMFbkKdOG/9khbUO2IKjhoMHddhaAa/P0mpz6Xkc4DqH8RjW
NE6XBQWOKE4dgnRSjsLMYUW/JtkIYEeLTV48QHdkAwJ7cdqZhwkabhsULxgQ9atiJ6mEYedZVOm2
FX1/0XlGwrtbWnf0MVZpVT0b7w0Jw7mjcRyvGpIMZlH0eTqFNM93LvhGhbMGWeWcMMwq3tlGY9BD
ACQbCPY0pXEJlX5WGHwKF/ewKfJboXf9LPHS5/vvcUt9+13Xyop7xUzxk/Aa/u3p1hDzs3QvM3L3
3/g9CV85AJbZGmqOHnrxxirSh3wNE2dnB8NL51JSZ+770IIMAyAhlFua/cUvlsmeQpaXSUyBPCQZ
LVicp96GJM/YKi+37HGZlLTYs1Wax9/omsyHWlp+L7LrjTq2ZDP/4HcrRBdMo+mX3mWf5cfiz1dm
+iOmO08FZOXXcdhEC7WsQWm8buGw2uh+i1rwunUOOB0ebzyej/4A35ex1DEDAAA=
NQC_MINER_COLLECTION_INPUT_6
cat > "$MINER_TEST_EVIDENCE/input.sha256" <<'NQC_COLLECTION_HASHES'
5307880cd7f274f5f0ac4eb222e19ca34fb0e0a9abd59a2970be50611a259f21  postgres.sql
4fe03449780702a9aa700540a473fa61396fb85fa60805fdf658e15a75741b0b  postgres_import.sql
90de39223b0265d8b2ca2d8ee73127571018040c7865917653d3444dcf8ef350  postgres_collection.sql
b5b1e02afe78a89f3cf5d94fe0f69122c3e1fc0b4752041722eebcd305c84fe6  fixtures.sql
cb984a7cc12cf34c59361a7b0a6da5e5bdba741956407581c0b6526a61f60dd6  fixture-verification.json
0a9340c1d0caf05662850fc6f471b12404be6f88a4a250219787f88b53ab9a9d  cases.sql
9ea5feff10121fdaebfcbcc157a6be2930fbf9f1a4dfdc6deabc20fcf6c8ca84  holder.sql
NQC_COLLECTION_HASHES

(cd "$MINER_TEST_EVIDENCE" && sha256sum -c input.sha256)
initdb -D "$MINER_TEST_ROOT/data" -U "$MINER_TEST_USER" --encoding=UTF8 --locale=C \
  --auth-local=peer --auth-host=reject > "$MINER_TEST_EVIDENCE/initdb.log" 2>&1
cat >> "$MINER_TEST_ROOT/data/postgresql.conf" <<EOF
listen_addresses = ''
unix_socket_directories = '$MINER_TEST_ROOT/s'
unix_socket_permissions = 0700
port = 55434
shared_buffers = '32MB'
max_connections = 10
max_parallel_workers = 0
EOF
cp "$MINER_TEST_ROOT/data/postgresql.conf" "$MINER_TEST_ROOT/data/pg_hba.conf" "$MINER_TEST_EVIDENCE/"
MINER_TEST_STARTED=1
pg_ctl -D "$MINER_TEST_ROOT/data" -l "$MINER_TEST_EVIDENCE/server.log" -w -t 60 start > "$MINER_TEST_EVIDENCE/startup.log" 2>&1
export PGOPTIONS='-c statement_timeout=90000 -c lock_timeout=30000'
MINER_TEST_PSQL=(psql -X -w -h "$MINER_TEST_ROOT/s" -p 55434 -U "$MINER_TEST_USER" -v ON_ERROR_STOP=1 -v VERBOSITY=verbose -P pager=off)
"${MINER_TEST_PSQL[@]}" -d postgres -c 'CREATE ROLE nqc_miner_import_owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION; CREATE ROLE nqc_miner_import_writer NOLOGIN NOSUPERUSER; CREATE ROLE nqc_miner_import_outsider NOLOGIN NOSUPERUSER;' > "$MINER_TEST_EVIDENCE/roles.log" 2>&1
createdb -w -h "$MINER_TEST_ROOT/s" -p 55434 -U "$MINER_TEST_USER" --maintenance-db=postgres -O nqc_miner_import_owner nqc_miner_v1 > "$MINER_TEST_EVIDENCE/database.log" 2>&1
"${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -c 'SET ROLE nqc_miner_import_owner' -f "$MINER_TEST_EVIDENCE/postgres.sql" > "$MINER_TEST_EVIDENCE/apply-base.log" 2>&1
"${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -c 'SET ROLE nqc_miner_import_owner' -f "$MINER_TEST_EVIDENCE/postgres_import.sql" > "$MINER_TEST_EVIDENCE/apply-importer.log" 2>&1
if "${MINER_TEST_PSQL[@]}" -d postgres -c 'SET ROLE nqc_miner_import_owner' -f "$MINER_TEST_EVIDENCE/postgres_collection.sql" > "$MINER_TEST_EVIDENCE/wrong-database.log" 2>&1; then
  printf 'FAILED: importer accepted foreign database\n' >&2; exit 1
fi
grep -q 'ERROR:  *P0001' "$MINER_TEST_EVIDENCE/wrong-database.log"
"${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -c 'SET ROLE nqc_miner_import_owner' -f "$MINER_TEST_EVIDENCE/postgres_collection.sql" > "$MINER_TEST_EVIDENCE/apply-collection.log" 2>&1
if "${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -c 'SET ROLE nqc_miner_import_owner' -f "$MINER_TEST_EVIDENCE/postgres_collection.sql" > "$MINER_TEST_EVIDENCE/duplicate-collection.log" 2>&1; then
  printf 'FAILED: importer installation overwritten\n' >&2; exit 1
fi
grep -q 'ERROR:  *42P07' "$MINER_TEST_EVIDENCE/duplicate-collection.log"
"${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -f "$MINER_TEST_EVIDENCE/fixtures.sql" > "$MINER_TEST_EVIDENCE/fixtures.log" 2>&1
printf 'MINER: importacion, duplicados, cuarentena y rollback...\n'
"${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -f "$MINER_TEST_EVIDENCE/cases.sql" > "$MINER_TEST_EVIDENCE/cases.log" 2>&1
[[ $(grep -c 'MINER_COLLECTION_PASS:' "$MINER_TEST_EVIDENCE/cases.log") == 33 ]]
for action in 'UPDATE nqc_miner_v1.journal_ledger SET sequence=sequence' 'DELETE FROM nqc_miner_v1.collection_quarantine' 'TRUNCATE nqc_miner_v1.collection_windows' 'UPDATE nqc_miner_v1.collections SET archive_id=archive_id'; do
  if "${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -c 'SET ROLE nqc_miner_import_writer' -c "$action" >> "$MINER_TEST_EVIDENCE/writer-denials.log" 2>&1; then
    printf 'FAILED: limited writer changed existing evidence\n' >&2; exit 1
  fi
done
[[ $(grep -c 'ERROR:  *42501' "$MINER_TEST_EVIDENCE/writer-denials.log") == 4 ]]
if "${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -c 'SET ROLE nqc_miner_import_outsider' -c "SELECT nqc_miner_v1.import_verified_collection('{}'::jsonb)" > "$MINER_TEST_EVIDENCE/outsider-denial.log" 2>&1; then
  printf 'FAILED: outsider executed importer\n' >&2; exit 1
fi
grep -q 'ERROR:  *42501' "$MINER_TEST_EVIDENCE/outsider-denial.log"

query() { "${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -qAtc "$1"; }
wait_for_query() {
  local attempt
  for ((attempt=0;attempt<100;attempt++)); do
    if [[ $(query "$1") == t ]]; then return 0; fi
    sleep 0.1
  done
  printf 'FAILED: timed out waiting for owned test session\n' >&2
  return 1
}
printf 'MINER: dos importadores concurrentes...\n'
PGAPPNAME=nqc_miner_collection_holder "${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -f "$MINER_TEST_EVIDENCE/holder.sql" > "$MINER_TEST_EVIDENCE/holder.log" 2>&1 &
MINER_HOLDER_PID=$!; MINER_TEST_CHILDREN+=("$MINER_HOLDER_PID")
wait_for_query "SELECT EXISTS(SELECT FROM pg_locks l JOIN pg_stat_activity a USING(pid) WHERE a.application_name='nqc_miner_collection_holder' AND a.datname='nqc_miner_v1' AND l.locktype='advisory' AND l.granted)"
for index in 1 2; do
  PGAPPNAME="nqc_miner_collection_waiter_$index" "${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -qAt -c 'SET ROLE nqc_miner_import_writer' \
    -c "SELECT nqc_miner_v1.import_verified_collection(payload) FROM nqc_miner_v1.test_inputs WHERE name='concurrent'" \
    > "$MINER_TEST_EVIDENCE/concurrent-$index.json" 2> "$MINER_TEST_EVIDENCE/concurrent-$index.stderr" &
  MINER_TEST_CHILDREN+=("$!")
done
wait "$MINER_HOLDER_PID"
wait "${MINER_TEST_CHILDREN[1]}"
wait "${MINER_TEST_CHILDREN[2]}"
grep -q 'MINER_COLLECTION_BOTH_WAITERS_BLOCKED' "$MINER_TEST_EVIDENCE/holder.log"
[[ $(cat "$MINER_TEST_EVIDENCE/concurrent-1.json" "$MINER_TEST_EVIDENCE/concurrent-2.json" | grep -c '"status": "imported"') == 1 ]]
[[ $(cat "$MINER_TEST_EVIDENCE/concurrent-1.json" "$MINER_TEST_EVIDENCE/concurrent-2.json" | grep -c '"status": "idempotent"') == 1 ]]
[[ $(query "SELECT (SELECT count(*)=4 FROM nqc_miner_v1.eligible_collection_ledger WHERE parent_run_id='pgcoll_concurrent') AND (SELECT count(*)=4 FROM nqc_miner_v1.eligible_collection_outbox WHERE parent_run_id='pgcoll_concurrent') AND (SELECT count(*)=2 FROM nqc_miner_v1.collection_windows WHERE parent_run_id='pgcoll_concurrent')") == t ]]
printf '{"status":"pass","blocked_importers":2,"committed_records":4,"committed_outbox":4}\n' > "$MINER_TEST_EVIDENCE/concurrency.json"

printf 'MINER: interrupcion de una sesion propia antes del commit...\n'
PGAPPNAME=nqc_miner_collection_interrupt "${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -qAt -c 'SET ROLE nqc_miner_import_writer' \
  -c "BEGIN; SELECT nqc_miner_v1.import_verified_collection(payload) FROM nqc_miner_v1.test_inputs WHERE name='interrupt'; SELECT pg_sleep(60); COMMIT;" \
  > "$MINER_TEST_EVIDENCE/interrupted-client.log" 2>&1 &
MINER_INTERRUPT_PID=$!; MINER_TEST_CHILDREN+=("$MINER_INTERRUPT_PID")
wait_for_query "SELECT EXISTS(SELECT FROM pg_stat_activity WHERE application_name='nqc_miner_collection_interrupt' AND datname='nqc_miner_v1' AND wait_event='PgSleep')"
query "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE application_name='nqc_miner_collection_interrupt' AND datname='nqc_miner_v1' AND wait_event='PgSleep'" > "$MINER_TEST_EVIDENCE/terminate-session.txt"
[[ $(cat "$MINER_TEST_EVIDENCE/terminate-session.txt") == t ]]
if wait "$MINER_INTERRUPT_PID"; then printf 'FAILED: interrupted transaction returned success\n' >&2; exit 1; fi
[[ $(query "SELECT NOT EXISTS(SELECT FROM nqc_miner_v1.runs WHERE run_id='pgcoll_interrupt' OR run_id IN (SELECT w->'journal'->'owner'->>'run_id' FROM nqc_miner_v1.test_inputs t CROSS JOIN LATERAL jsonb_array_elements(t.payload->'windows') w WHERE t.name='interrupt')) AND NOT EXISTS(SELECT FROM nqc_miner_v1.collections WHERE parent_run_id='pgcoll_interrupt')") == t ]]
"${MINER_TEST_PSQL[@]}" -d nqc_miner_v1 -qAt -c 'SET ROLE nqc_miner_import_writer' \
  -c "SELECT nqc_miner_v1.import_verified_collection(payload) FROM nqc_miner_v1.test_inputs WHERE name='interrupt'" \
  > "$MINER_TEST_EVIDENCE/interruption-retry.json" 2> "$MINER_TEST_EVIDENCE/interruption-retry.stderr"
grep -q '"status": "imported"' "$MINER_TEST_EVIDENCE/interruption-retry.json"
[[ $(query "SELECT (SELECT count(*)=4 FROM nqc_miner_v1.eligible_collection_ledger WHERE parent_run_id='pgcoll_interrupt') AND (SELECT count(*)=4 FROM nqc_miner_v1.eligible_collection_outbox WHERE parent_run_id='pgcoll_interrupt')") == t ]]
printf '{"status":"pass","uncommitted_rows_absent":true,"retry_records":4,"backend_termination_injected":true}\n' > "$MINER_TEST_EVIDENCE/interruption.json"

printf 'MINER: reinicio y comparacion de todos los datos...\n'
query 'SELECT version(); SHOW listen_addresses; SHOW unix_socket_directories; SHOW fsync; SHOW synchronous_commit;' > "$MINER_TEST_EVIDENCE/server-settings.txt"
MINER_SNAPSHOT="SELECT jsonb_build_object('collections',(SELECT jsonb_agg(c ORDER BY parent_run_id) FROM nqc_miner_v1.collections c),'windows',(SELECT jsonb_agg(w ORDER BY parent_run_id,window_index) FROM nqc_miner_v1.collection_windows w),'receipts',(SELECT jsonb_agg(r ORDER BY parent_run_id,receipt_sequence) FROM nqc_miner_v1.collection_receipts r),'revocations',(SELECT jsonb_agg(q ORDER BY parent_run_id) FROM nqc_miner_v1.collection_quarantine q),'eligible_ledger',(SELECT jsonb_agg(l ORDER BY parent_run_id,window_index,sequence) FROM nqc_miner_v1.eligible_collection_ledger l),'eligible_outbox',(SELECT jsonb_agg(o ORDER BY parent_run_id,window_index,sequence) FROM nqc_miner_v1.eligible_collection_outbox o),'identity',(SELECT jsonb_agg(i) FROM nqc_miner_v1.import_identity i),'runs',(SELECT jsonb_agg(r ORDER BY run_id) FROM nqc_miner_v1.runs r),'ledger',(SELECT jsonb_agg(l ORDER BY run_id,sequence) FROM nqc_miner_v1.journal_ledger l),'outbox',(SELECT jsonb_agg(o ORDER BY run_id,sequence,topic) FROM nqc_miner_v1.outbox o),'quarantine',(SELECT jsonb_agg(q ORDER BY run_id) FROM nqc_miner_v1.import_quarantine q),'registry',(SELECT jsonb_agg(m ORDER BY run_id,mine_id) FROM nqc_miner_v1.mine_registry m),'gates',(SELECT jsonb_agg(g ORDER BY run_id,mine_id,gate_kind,report_sha256) FROM nqc_miner_v1.gate_reports g),'lifecycle',(SELECT jsonb_agg(j ORDER BY run_id,mine_id,lifecycle_version) FROM nqc_miner_v1.lifecycle_journal j))"
query "$MINER_SNAPSHOT" > "$MINER_TEST_EVIDENCE/before-restart.json"
pg_ctl -D "$MINER_TEST_ROOT/data" -m fast -w -t 60 restart >> "$MINER_TEST_EVIDENCE/startup.log" 2>&1
query "$MINER_SNAPSHOT" > "$MINER_TEST_EVIDENCE/after-restart.json"
cmp "$MINER_TEST_EVIDENCE/before-restart.json" "$MINER_TEST_EVIDENCE/after-restart.json"
printf '33 SQL assertions, permissions, concurrency, interruption and restart passed.\n'
